import{_ as t,o as h,c as i,a2 as a}from"./chunks/framework.BBd5PKnH.js";const c="/dev-notes/assets/03-morning-evening-planets.Dr2Snaan.svg",o="/dev-notes/assets/04-morning-evening-longitude-rule.Cid4JI_O.svg",g="/dev-notes/assets/05-masculine-feminine-quadrants.uD_McZyb.svg",r="data:image/svg+xml;base64,",p=JSON.parse('{"title":"Giới tính của các hành tinh, Phần 2: Solar phase, góc phần tư và vĩ độ thiên thể","description":"","frontmatter":{},"headers":[],"relativePath":"astro/planets/gender/gender-of-planets-part-2-phase-quadrant-latitude.md","filePath":"astro/planets/gender/gender-of-planets-part-2-phase-quadrant-latitude.md"}'),d={name:"astro/planets/gender/gender-of-planets-part-2-phase-quadrant-latitude.md"};function u(s,n,e,l,m,b){return h(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="gioi-tinh-cua-cac-hanh-tinh-phan-2-solar-phase-goc-phan-tu-va-vi-đo-thien-the" tabindex="-1">Giới tính của các hành tinh, Phần 2: Solar phase, góc phần tư và vĩ độ thiên thể <a class="header-anchor" href="#gioi-tinh-cua-cac-hanh-tinh-phan-2-solar-phase-goc-phan-tu-va-vi-đo-thien-the" aria-label="Permalink to &quot;Giới tính của các hành tinh, Phần 2: Solar phase, góc phần tư và vĩ độ thiên thể&quot;">​</a></h1><p><em>(Demetra George, Ancient Astrology in Theory and Practice, Vol. I, Chương 5, Figure 5, Figure 6)</em></p><blockquote><p><strong>[Sách]</strong> = dịch và giải nghĩa từ các trang bạn chụp. <strong>[Bổ sung]</strong> = phần mình diễn giải thêm hoặc tính thêm, nên đối chiếu khi đọc tiếp. Phần này đi cùng <code>gender-of-planets-part-1-concepts-signs-and-range.md</code> (khái niệm, giới tính của sign, Table 7 và Table 8). Các hình nằm trong thư mục <code>images/</code>. Mình không có công cụ tra cứu. Tên Paulus và các nhận định lịch sử là những gì sách ghi, hãy kiểm tra lại trước khi trích dẫn.</p></blockquote><hr><h2 id="tom-tat-nhanh" tabindex="-1">Tóm tắt nhanh <a class="header-anchor" href="#tom-tat-nhanh" aria-label="Permalink to &quot;Tóm tắt nhanh&quot;">​</a></h2><ol><li><strong>Solar phase</strong>: hành tinh mọc <strong>trước</strong> Sun (buổi sáng) thì <strong>nam hóa</strong>, mọc <strong>sau</strong> Sun (buổi chiều) thì <strong>nữ hóa</strong>.</li><li>Cách tính bằng số: hành tinh có <strong>số độ nhỏ hơn Sun</strong> (trong 180°) là buổi sáng, <strong>lớn hơn</strong> là buổi chiều.</li><li>Phần chỉnh nâng cao: vùng điều chỉnh chỉ nằm từ <strong>15° đến 120°</strong> tính từ Sun.</li><li><strong>Góc phần tư</strong>: Asc đến MC và Dsc đến IC là <strong>nam</strong>; MC đến Dsc và IC đến Asc là <strong>nữ</strong>.</li><li><strong>Vĩ độ thiên thể</strong>: phía <strong>bắc</strong> ecliptic nam hóa, phía <strong>nam</strong> nữ hóa. Đừng nhầm với declination.</li><li>Sách chưa rõ quadrant tính theo <strong>whole sign</strong> hay theo <strong>độ chính xác của các góc</strong>. Trong lá số mẫu, hai cách cho kết quả khác nhau với Moon và Mercury.</li></ol><hr><h2 id="_1-solar-phase-đieu-kien-so-2" tabindex="-1">1. Solar phase (điều kiện số 2) <a class="header-anchor" href="#_1-solar-phase-đieu-kien-so-2" aria-label="Permalink to &quot;1. Solar phase (điều kiện số 2)&quot;">​</a></h2><h3 id="ban-dich" tabindex="-1">Bản dịch <a class="header-anchor" href="#ban-dich" aria-label="Permalink to &quot;Bản dịch&quot;">​</a></h3><blockquote><p><strong>Solar phase</strong> của hành tinh là điều kiện thứ hai để đánh giá việc điều chỉnh giới tính. Một hành tinh trở nên <strong>nam hóa</strong> hơn khi nó được thấy trên <strong>bầu trời buổi sáng, mọc trước (đi trước) Sun</strong>, và <strong>nữ hóa</strong> hơn khi nó xuất hiện trên <strong>bầu trời buổi chiều, sau (theo sau) Sun đã lặn</strong>. Chúng ta có thể hình dung rằng phần lớn mọi người tràn đầy năng lượng và sẵn sàng hoạt động vào buổi sáng, và có xu hướng nghỉ ngơi, thư giãn vào buổi chiều.</p><p>Để xác định một hành tinh thuộc pha buổi sáng hay buổi chiều, hãy <strong>xoay lá số sao cho Sun nằm ở vị trí Ascendant</strong>, tức điểm mặt trời mọc. Nhớ rằng các hành tinh chuyển động theo chuyển động ngày, nên lúc bình minh chúng leo lên qua Ascendant và đi <strong>theo chiều kim đồng hồ</strong>, trong đó Midheaven là giữa trưa, Descendant là hoàng hôn, và Nadir là nửa đêm. Nếu hành tinh đang xét thuộc <strong>buổi sáng</strong>, nó đã mọc trước Sun và <strong>đi trước Sun</strong> (tới độ đối của Sun), nhưng có <strong>kinh độ hoàng đạo nhỏ hơn Sun</strong>. (Sun ở 15° Leo, Mercury ở 25° Cancer.) Nếu hành tinh thuộc <strong>buổi chiều</strong>, nó mọc sau Sun và <strong>đi sau Sun</strong> (tới độ đối của Sun), nhưng có <strong>kinh độ hoàng đạo lớn hơn Sun</strong>. (Sun ở 15° Leo, Mercury ở 5° Virgo.) Sun có thể nằm bất cứ đâu trong lá số; yếu tố quyết định đơn giản là hành tinh đang xét <strong>đi trước hay đi sau Sun theo chuyển động ngày</strong>. Chúng ta sẽ giải thích sao/hành tinh buổi sáng và buổi chiều đầy đủ hơn ở Phần Ba.</p></blockquote><p><strong>Chú thích Figure 5:</strong> <em>Sun mọc ở 15° Leo (lặn ở 15° Aquarius). Mercury ở 25° Cancer mọc vào buổi sáng, trước lúc bình minh; Mercury ở 5° Virgo có thể được thấy xuất hiện trên bầu trời buổi chiều sau hoàng hôn.</em></p><h3 id="phan-chinh-nang-cao-ban-dich" tabindex="-1">Phần chỉnh nâng cao (bản dịch) <a class="header-anchor" href="#phan-chinh-nang-cao-ban-dich" aria-label="Permalink to &quot;Phần chỉnh nâng cao (bản dịch)&quot;">​</a></h3><blockquote><p>Học viên nâng cao có thể tinh chỉnh đánh giá này bằng cách lưu ý rằng: <strong>khu vực nam hóa</strong> của chu kỳ solar phase kéo dài <strong>về phía trước từ độ thứ 15 phía trước Sun tới độ thứ 120 tính từ Sun</strong>, hoặc ngay trước trạm nghịch hành (retrograde station). <strong>Khu vực nữ hóa</strong> của chu kỳ solar phase kéo dài <strong>về phía sau từ độ thứ 15 phía sau Sun tới độ thứ 120 tính từ Sun</strong>, hoặc ngay sau trạm thuận hành (direct station).</p></blockquote><h3 id="hinh-1-figure-5-ve-lai-co-them-cac-vung-15°-va-120°" tabindex="-1">Hình 1: Figure 5 vẽ lại, có thêm các vùng 15° và 120° <a class="header-anchor" href="#hinh-1-figure-5-ve-lai-co-them-cac-vung-15°-va-120°" aria-label="Permalink to &quot;Hình 1: Figure 5 vẽ lại, có thêm các vùng 15° và 120°&quot;">​</a></h3><p><img src="'+c+'" alt="Hành tinh buổi sáng và buổi chiều"></p><p><strong>Cách đọc hình:</strong></p><ul><li>Bánh xe đã <strong>xoay sao cho Sun nằm ở Asc</strong> (bên trái, giờ mặt trời mọc).</li><li>Các hành tinh đi <strong>theo chiều kim đồng hồ</strong>: lên qua đỉnh (Midday, MC), xuống ở bên phải (Sunset, Dsc), rồi qua đáy (Midnight, IC).</li><li><strong>Phía trên</strong> đường chân trời lúc Sun mọc là các hành tinh <strong>đã mọc trước Sun</strong> (buổi sáng, màu cam, nam hóa).</li><li><strong>Phía dưới</strong> là các hành tinh <strong>chưa mọc, sẽ mọc sau Sun</strong> (buổi chiều, màu xanh, nữ hóa).</li><li>Mercury 25° Cancer nằm trên đường chân trời nên là buổi sáng. Mercury 5° Virgo nằm dưới nên là buổi chiều.</li></ul><h3 id="hinh-2-quy-tac-theo-so-đo" tabindex="-1">Hình 2: Quy tắc theo số độ <a class="header-anchor" href="#hinh-2-quy-tac-theo-so-đo" aria-label="Permalink to &quot;Hình 2: Quy tắc theo số độ&quot;">​</a></h3><p><img src="'+o+'" alt="Quy tắc số độ buổi sáng và buổi chiều"></p><h3 id="phan-tich" tabindex="-1">Phân tích <a class="header-anchor" href="#phan-tich" aria-label="Permalink to &quot;Phân tích&quot;">​</a></h3><p><strong>a) Vì sao &quot;đi trước Sun&quot; lại là &quot;số độ nhỏ hơn&quot;?</strong> [Bổ sung, giải thích chỗ dễ gây rối]</p><p>Có hai chiều chuyển động khác nhau:</p><ul><li>Trong một năm, Sun đi <strong>chậm theo chiều tăng độ</strong> (Cancer → Leo → Virgo).</li><li>Trong một ngày, <strong>bầu trời quay theo chiều ngược lại</strong> (mọc ở phía đông, lặn ở phía tây).</li></ul><p>Vì bầu trời quay như vậy, vật nào đứng ở <strong>phía &quot;sau&quot; Sun trên vòng hoàng đạo</strong> (số độ nhỏ hơn) sẽ được bầu trời đưa lên <strong>trước</strong>. Nên &quot;đi trước Sun theo chuyển động ngày&quot; và &quot;số độ nhỏ hơn&quot; là <strong>cùng một thứ</strong>, chỉ nhìn từ hai chiều khác nhau.</p><p><strong>b) Cách tính bằng số</strong> [Bổ sung]:</p><ol><li>Đổi mỗi vị trí ra số độ tuyệt đối: 30 × (số thứ tự sign, Aries là 0) + độ trong sign. Ví dụ 15° Leo = 30×4 + 15 = <strong>135°</strong>.</li><li>Tính chênh lệch <strong>d = (độ hành tinh − độ Sun)</strong>, cộng 360 nếu âm.</li><li>Nếu <strong>d lớn hơn 180</strong>: hành tinh nằm &quot;sau&quot; Sun trên vòng hoàng đạo, là <strong>buổi sáng</strong>, khoảng cách tới Sun là <strong>360 − d</strong>.</li><li>Nếu <strong>d nhỏ hơn 180</strong>: là <strong>buổi chiều</strong>, khoảng cách tới Sun là <strong>d</strong>.</li></ol><p>Ví dụ theo sách (Sun 15° Leo = 135°):</p><ul><li>Mercury 25° Cancer = 115°. d = 115 − 135 = −20 → 340. Lớn hơn 180 nên <strong>buổi sáng</strong>, cách Sun 20°.</li><li>Mercury 5° Virgo = 155°. d = 20. Nhỏ hơn 180 nên <strong>buổi chiều</strong>, cách Sun 20°.</li></ul><p><strong>c) Phần chỉnh nâng cao: vùng 15° đến 120°</strong> [Bổ sung, cách mình hiểu]</p><table tabindex="0"><thead><tr><th>Khoảng cách tới Sun</th><th>Điều chỉnh giới tính</th></tr></thead><tbody><tr><td>Trong 15°</td><td>Không điều chỉnh (hành tinh sát Sun, bị lu mờ)</td></tr><tr><td>15° đến 120°</td><td><strong>Có điều chỉnh</strong>: phía trước = nam hóa, phía sau = nữ hóa</td></tr><tr><td>Quá 120°</td><td>Không điều chỉnh (gần trạm nghịch hành hoặc thuận hành)</td></tr></tbody></table><p>Sách nói vùng điều chỉnh kéo dài &quot;tới độ 120 hoặc ngay trước/sau trạm&quot;. Mình hiểu hai đầu (trong 15° và quá 120°) là <strong>không còn điều chỉnh</strong>, nhưng sách không nói thẳng điều này trong các trang đã gửi.</p><p><strong>d) Mercury và Venus không bao giờ chạm mốc 120°</strong> [Bổ sung, kiến thức chung]: Mercury luôn ở rất gần Sun (cách tối đa khoảng 28°), Venus khoảng 47°. Nên với hai hành tinh này, vùng điều chỉnh chạy từ 15° tới khoảng cách tối đa của chúng. Chỉ các hành tinh ngoài (Mars, Jupiter, Saturn) mới có thể vượt 120°.</p><p><strong>e) Hai liên hệ thú vị</strong></p><ul><li><strong>Venus buổi sáng và buổi chiều</strong> [Bổ sung]: ở Table 3 bạn đã đọc Ishtar là <strong>nữ thần chiến tranh khi là sao Mai</strong> và <strong>nữ thần tình yêu khi là sao Hôm</strong>. Quy tắc này khớp: sao Mai (buổi sáng) thì <strong>nam hóa</strong> (chủ động, tranh đấu), sao Hôm (buổi chiều) thì <strong>nữ hóa</strong> (êm dịu, tình yêu). Cũng khớp với ghi chú trong <code>venus.md</code> rằng Venus mọc trước Sun thường được coi là chủ động hơn.</li><li><strong>Moon theo pha trăng</strong> [Bổ sung, suy ra từ quy tắc]: trăng <strong>đang tròn dần</strong> (đi trước Sun trên vòng hoàng đạo, hiện ra buổi chiều) thì thuộc <strong>buổi chiều</strong> (nữ hóa). Trăng <strong>đang khuyết dần</strong> (đi sau Sun, mọc trước Sun) thì thuộc <strong>buổi sáng</strong> (nam hóa). Sách có thể xử lý riêng Moon ở Phần Ba, nên đây chỉ là suy luận từ quy tắc chung.</li></ul><p><strong>f) Điều kiện này khớp với note trước:</strong> &quot;oriental&quot; (mọc trước Sun) và &quot;occidental&quot; (mọc sau Sun) mình đã dùng ở note về sect và các file hành tinh chính là <strong>buổi sáng</strong> và <strong>buổi chiều</strong> ở đây.</p><hr><h2 id="_2-goc-phan-tu-đieu-kien-so-3" tabindex="-1">2. Góc phần tư (điều kiện số 3) <a class="header-anchor" href="#_2-goc-phan-tu-đieu-kien-so-3" aria-label="Permalink to &quot;2. Góc phần tư (điều kiện số 3)&quot;">​</a></h2><h3 id="ban-dich-1" tabindex="-1">Bản dịch <a class="header-anchor" href="#ban-dich-1" aria-label="Permalink to &quot;Bản dịch&quot;">​</a></h3><blockquote><p><strong>Vị trí góc phần tư</strong> của hành tinh cũng ảnh hưởng đến việc điều chỉnh giới tính. Các house trong góc phần tư <strong>từ Ascendant đến Midheaven là nam</strong>; từ <strong>Midheaven đến Descendant là nữ</strong>; các house từ <strong>Descendant đến IC là nam</strong>, và từ <strong>IC đến Ascendant là nữ</strong>. Một hành tinh trở nên nam hơn khi ở các góc phần tư nam, có lẽ vì chuyển động của Sun đang <strong>đi lên hướng tới các điểm culminating hoặc anti-culminating</strong> (đỉnh hoặc đáy). Hành tinh trở nên nữ hơn khi ở các góc phần tư nữ, có lẽ do <strong>hướng đi xuống (declining) của Sun</strong>. Các văn bản <strong>không hoàn toàn rõ</strong> liệu các góc phần tư này được phân định theo whole sign hay theo độ chính xác của các góc, dù <strong>Paulus có nêu độ chính xác</strong> trong phần bàn về chủ đề này.</p></blockquote><p><strong>Chú thích Figure 6:</strong> <em>Theo chuyển động ngày, các góc phần tư nam kéo dài từ ASC đến MC, và từ DSC đến IC. Các góc phần tư nữ kéo dài từ MC đến DSC, và từ IC đến ASC.</em></p><h3 id="hinh-3-figure-6-ve-lai-co-house-va-huong-chuyen-đong" tabindex="-1">Hình 3: Figure 6 vẽ lại, có house và hướng chuyển động <a class="header-anchor" href="#hinh-3-figure-6-ve-lai-co-house-va-huong-chuyen-đong" aria-label="Permalink to &quot;Hình 3: Figure 6 vẽ lại, có house và hướng chuyển động&quot;">​</a></h3><p><img src="'+g+'" alt="Bốn góc phần tư nam và nữ"></p><p>(Lá số của sách: Asc 17° Scorpio, MC 28° Leo, Dsc 17° Taurus, IC 28° Aquarius. Hình chia mỗi góc phần tư thành 3 house đều nhau cho dễ nhìn.)</p><h3 id="phan-tich-1" tabindex="-1">Phân tích <a class="header-anchor" href="#phan-tich-1" aria-label="Permalink to &quot;Phân tích&quot;">​</a></h3><p><strong>a) Bảng góc phần tư</strong> [Sách, thêm cột house và hướng đi]:</p><table tabindex="0"><thead><tr><th>Góc phần tư (theo chuyển động ngày)</th><th>House</th><th>Giới</th><th>Sun đang làm gì (diễn giải của sách)</th></tr></thead><tbody><tr><td>Asc → MC</td><td>12, 11, 10</td><td><strong>Nam</strong></td><td>Đang đi lên tới đỉnh (MC)</td></tr><tr><td>MC → Dsc</td><td>9, 8, 7</td><td><strong>Nữ</strong></td><td>Đang đi xuống từ đỉnh</td></tr><tr><td>Dsc → IC</td><td>6, 5, 4</td><td><strong>Nam</strong></td><td>Đang tiến tới đáy (IC)</td></tr><tr><td>IC → Asc</td><td>3, 2, 1</td><td><strong>Nữ</strong></td><td>Đang rời khỏi đáy</td></tr></tbody></table><p><strong>b) Cách nhớ</strong> [Bổ sung, diễn giải theo câu &quot;perhaps because...&quot; của sách]: <strong>tiến tới điểm cực (MC hoặc IC) = nam; rời khỏi điểm cực = nữ</strong>. Giống như việc leo dốc (nam, đang tăng lực) so với xuống dốc (nữ, đang buông).</p><p><strong>c) Nối với angularity</strong> [Bổ sung]: bài Angularity chia house thành succedent (tiến tới góc), angular (ở góc), cadent (rời góc). Quadrant ở đây là một cách chia khác, <strong>chỉ dùng hai góc MC và IC</strong> làm điểm cực. Hai cách chia này khác nhau, đừng nhầm lẫn.</p><p><strong>d) Cách xác định quadrant bằng số độ</strong> [Bổ sung]:</p><p>Đi theo chiều tăng độ trên vòng hoàng đạo, bốn góc nằm theo thứ tự <strong>MC → Asc → IC → Dsc → MC</strong>. Các khoảng giữa:</p><table tabindex="0"><thead><tr><th>Khoảng (theo độ tăng)</th><th>Giới</th></tr></thead><tbody><tr><td>Từ MC đến Asc</td><td>Nam (Asc → MC)</td></tr><tr><td>Từ Asc đến IC</td><td>Nữ (IC → Asc)</td></tr><tr><td>Từ IC đến Dsc</td><td>Nam (Dsc → IC)</td></tr><tr><td>Từ Dsc đến MC</td><td>Nữ (MC → Dsc)</td></tr></tbody></table><p>Kiểm tra với lá số của sách: MC 28° Leo (148°), Asc 17° Scorpio (227°). Khoảng 148° đến 227° gồm Leo (từ 28°), Virgo, Libra, Scorpio (đến 17°): đúng là cung nam ở góc trên bên trái của Figure 6.</p><p><strong>e) Whole sign hay độ chính xác?</strong> Sách nói các văn bản không rõ. Hai cách xác định cho kết quả khác nhau, như ở lá số mẫu dưới đây (mục 4).</p><hr><h2 id="_3-vi-đo-thien-the-đieu-kien-so-4" tabindex="-1">3. Vĩ độ thiên thể (điều kiện số 4) <a class="header-anchor" href="#_3-vi-đo-thien-the-đieu-kien-so-4" aria-label="Permalink to &quot;3. Vĩ độ thiên thể (điều kiện số 4)&quot;">​</a></h2><h3 id="ban-dich-2" tabindex="-1">Bản dịch <a class="header-anchor" href="#ban-dich-2" aria-label="Permalink to &quot;Bản dịch&quot;">​</a></h3><blockquote><p>Điều chỉnh giới tính cuối cùng là <strong>vĩ độ thiên thể (celestial latitude)</strong> của hành tinh. Vĩ độ thiên thể là khoảng cách của hành tinh <strong>về phía bắc hoặc phía nam của ecliptic</strong>. Hành tinh ở <strong>phía bắc ecliptic trở nên nam hơn</strong>, còn hành tinh ở <strong>phía nam ecliptic trở nên nữ hơn</strong>. Nhiều phần mềm chiêm tinh có báo cáo về vĩ độ của hành tinh. Hãy chắc chắn phân biệt điều này với <strong>declination</strong> của hành tinh, tức khoảng cách về phía bắc hoặc phía nam của <strong>xích đạo thiên cầu (celestial equator)</strong>, và được dùng trong nhiều cách diễn giải &quot;out of bounds&quot;.</p></blockquote><h3 id="hinh-4-vi-đo-khac-declination-nhu-the-nao" tabindex="-1">Hình 4: Vĩ độ khác declination như thế nào <a class="header-anchor" href="#hinh-4-vi-đo-khac-declination-nhu-the-nao" aria-label="Permalink to &quot;Hình 4: Vĩ độ khác declination như thế nào&quot;">​</a></h3><p><img src="'+r+'" alt="Celestial latitude và declination"></p><h3 id="phan-tich-2" tabindex="-1">Phân tích <a class="header-anchor" href="#phan-tich-2" aria-label="Permalink to &quot;Phân tích&quot;">​</a></h3><p><strong>a) Ecliptic là gì?</strong> [Bổ sung, kiến thức chung] Ecliptic là <strong>đường đi biểu kiến của Sun</strong> trên bầu trời trong một năm, và là &quot;đường chuẩn&quot; của vòng hoàng đạo (12 sign nằm dọc theo nó). Xích đạo thiên cầu là đường xích đạo của Trái Đất chiếu lên bầu trời. Hai đường này <strong>nghiêng nhau khoảng 23.4°</strong>.</p><p><strong>b) Hai cách đo &quot;lệch bắc hay nam&quot;</strong> [Sách, giải thích thêm]:</p><table tabindex="0"><thead><tr><th></th><th>Đo so với</th><th>Dùng làm gì</th></tr></thead><tbody><tr><td><strong>Vĩ độ thiên thể (latitude)</strong></td><td>Ecliptic</td><td>Điều kiện đổi giới tính (chương này)</td></tr><tr><td><strong>Declination</strong></td><td>Xích đạo thiên cầu</td><td>Cách đọc &quot;out of bounds&quot;</td></tr></tbody></table><p>Như trong hình, một hành tinh có thể nằm <strong>phía nam ecliptic</strong> (vĩ độ nam, nữ hóa) nhưng vẫn <strong>phía bắc xích đạo thiên cầu</strong> (declination bắc). Hai con số này <strong>không trùng nhau</strong>, nên phải lấy đúng cột trong phần mềm.</p><p><strong>c) Sun luôn có vĩ độ 0</strong> [Bổ sung]: vì ecliptic được định nghĩa là đường Sun đi, Sun luôn nằm ngay trên đó. Nên vĩ độ <strong>không điều chỉnh</strong> giới tính của Sun.</p><p><strong>d) Moon và các hành tinh khác</strong> [Bổ sung, kiến thức chung]: Moon lệch bắc nam đáng kể (khoảng vài độ, và đổi hướng trong khoảng nửa tháng), nên điều kiện vĩ độ của Moon thay đổi nhanh. Các hành tinh khác thường lệch ít hơn, và thay đổi chậm.</p><p><strong>e) Lưu ý về dữ liệu</strong>: bảng lá số mẫu bạn gửi <strong>không có cột vĩ độ thiên thể</strong>, nên mình chưa tính được điều kiện này. Gợi ý: thêm cột &quot;Latitude&quot; (thường ký hiệu Lat, Br, hoặc β trong phần mềm) vào bảng, và nhớ <strong>không nhầm với Declination</strong>.</p><p><strong>f) Cách nhớ</strong> [Bổ sung]: bắc là &quot;phía trên&quot; (nam hóa), nam là &quot;phía dưới&quot; (nữ hóa). Nếu phần mềm hiển thị số <strong>dương</strong> cho phía bắc và <strong>âm</strong> cho phía nam thì dương là nam hóa, âm là nữ hóa.</p><hr><h2 id="_4-ap-dung-vao-la-so-mau-bo-sung" tabindex="-1">4. Áp dụng vào lá số mẫu [Bổ sung] <a class="header-anchor" href="#_4-ap-dung-vao-la-so-mau-bo-sung" aria-label="Permalink to &quot;4. Áp dụng vào lá số mẫu [Bổ sung]&quot;">​</a></h2><p>Lá số mẫu: whole sign, Asc ≈ 26° Libra, lá số đêm. Các độ của góc (Asc ≈ 26° Libra, MC ≈ 26° Cancer, Dsc ≈ 26° Aries, IC ≈ 26° Capricorn) là <strong>ước lượng từ hình phần mềm</strong>.</p><h3 id="buoc-1-solar-phase-tinh-bang-so" tabindex="-1">Bước 1: solar phase (tính bằng số) <a class="header-anchor" href="#buoc-1-solar-phase-tinh-bang-so" aria-label="Permalink to &quot;Bước 1: solar phase (tính bằng số)&quot;">​</a></h3><p>Sun = 3° Aquarius = 303°.</p><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Độ</th><th>d = độ − 303 (cộng 360 nếu âm)</th><th>Pha</th><th>Cách Sun</th><th>Trong vùng 15° đến 120°?</th><th>Điều chỉnh</th></tr></thead><tbody><tr><td>Moon</td><td>191°</td><td>248</td><td>Sáng (đang khuyết)</td><td>112°</td><td>Có</td><td>Nam hóa</td></tr><tr><td>Mercury</td><td>282°</td><td>339</td><td>Sáng</td><td>21°</td><td>Có</td><td>Nam hóa</td></tr><tr><td>Venus</td><td>257°</td><td>314</td><td>Sáng (sao Mai)</td><td>46°</td><td>Có</td><td>Nam hóa</td></tr><tr><td>Mars</td><td>244°</td><td>301</td><td>Sáng</td><td>59°</td><td>Có</td><td>Nam hóa</td></tr><tr><td>Jupiter ℞</td><td>134°</td><td>191</td><td>Sáng</td><td>169°</td><td><strong>Không (quá 120°)</strong></td><td>Không</td></tr><tr><td>Saturn ℞</td><td>83°</td><td>140</td><td>Chiều</td><td>140°</td><td><strong>Không (quá 120°)</strong></td><td>Không</td></tr></tbody></table><h3 id="buoc-2-goc-phan-tu-hai-cach" tabindex="-1">Bước 2: góc phần tư (hai cách) <a class="header-anchor" href="#buoc-2-goc-phan-tu-hai-cach" aria-label="Permalink to &quot;Bước 2: góc phần tư (hai cách)&quot;">​</a></h3><p>Các khoảng theo độ (ước lượng): MC→Asc là 116° đến 206° (nam), Asc→IC là 206° đến 296° (nữ), IC→Dsc là 296° đến 386° (nam), Dsc→MC là 26° đến 116° (nữ).</p><table tabindex="0"><thead><tr><th>Hành tinh</th><th>House (whole sign)</th><th>Quadrant theo house</th><th>Độ</th><th>Quadrant theo độ</th></tr></thead><tbody><tr><td>Sun</td><td>5</td><td>Nam (6, 5, 4)</td><td>303°</td><td>Nam</td></tr><tr><td>Moon</td><td>1</td><td><strong>Nữ</strong> (3, 2, 1)</td><td>191°</td><td><strong>Nam</strong></td></tr><tr><td>Mercury</td><td>4</td><td><strong>Nam</strong> (6, 5, 4)</td><td>282°</td><td><strong>Nữ</strong></td></tr><tr><td>Venus</td><td>3</td><td>Nữ</td><td>257°</td><td>Nữ</td></tr><tr><td>Mars</td><td>3</td><td>Nữ</td><td>244°</td><td>Nữ</td></tr><tr><td>Jupiter</td><td>11</td><td>Nam (12, 11, 10)</td><td>134°</td><td>Nam</td></tr><tr><td>Saturn</td><td>9</td><td>Nữ (9, 8, 7)</td><td>83°</td><td>Nữ</td></tr></tbody></table><p><strong>Hai hành tinh cho kết quả khác nhau theo cách đo: Moon và Mercury.</strong> Đây chính là chỗ sách nói &quot;các văn bản không rõ&quot;. Moon ở 11° Libra nằm cùng sign với Asc nên là house 1 (whole sign), nhưng về độ nó đã <strong>nằm trên đường chân trời, mọc trước điểm Asc</strong> khoảng 15°. Mercury ở 12° Capricorn thuộc house 4, nhưng về độ nó đã <strong>đi qua IC</strong> khoảng 14°.</p><h3 id="buoc-3-vi-đo-thien-the" tabindex="-1">Bước 3: vĩ độ thiên thể <a class="header-anchor" href="#buoc-3-vi-đo-thien-the" aria-label="Permalink to &quot;Bước 3: vĩ độ thiên thể&quot;">​</a></h3><p>Chưa có dữ liệu. Sun luôn bằng 0 (không điều chỉnh).</p><h3 id="buoc-4-tong-hop-so-bo" tabindex="-1">Bước 4: tổng hợp sơ bộ <a class="header-anchor" href="#buoc-4-tong-hop-so-bo" aria-label="Permalink to &quot;Bước 4: tổng hợp sơ bộ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hành tinh</th><th>Giới gốc</th><th>Sign</th><th>Phase</th><th>Quadrant</th><th>Xu hướng sơ bộ (chưa tính latitude)</th></tr></thead><tbody><tr><td>Sun</td><td>Nam</td><td>Nam (hợp)</td><td>Không áp dụng</td><td>Nam</td><td>Nam tính, nghiêng <strong>cực kỳ nam tính</strong></td></tr><tr><td>Moon</td><td>Nữ</td><td>Nam</td><td>Nam hóa</td><td>Nữ (house) hoặc nam (độ)</td><td><strong>Nữ tính bị nam hóa</strong> (nếu quadrant theo độ thì cả 3 điều kiện đều nam hóa)</td></tr><tr><td>Mercury</td><td>Nam (linh hoạt)</td><td>Nữ</td><td>Nam hóa</td><td>Nam (house) hoặc nữ (độ)</td><td><strong>Chưa rõ</strong>, phụ thuộc cách đo quadrant</td></tr><tr><td>Venus</td><td>Nữ</td><td>Nam</td><td>Nam hóa</td><td>Nữ</td><td><strong>Nữ tính bị nam hóa</strong> (2 trên 3 điều kiện nam hóa)</td></tr><tr><td>Mars</td><td>Nam</td><td>Nam (hợp)</td><td>Nam hóa</td><td>Nữ</td><td><strong>Nam tính</strong>, nghiêng cực kỳ nam tính (2 trên 3)</td></tr><tr><td>Jupiter</td><td>Nam</td><td>Nam (hợp)</td><td>Không điều chỉnh</td><td>Nam</td><td><strong>Nam tính</strong>, nghiêng cực kỳ nam tính</td></tr><tr><td>Saturn</td><td>Nam</td><td>Nam (hợp)</td><td>Không điều chỉnh</td><td>Nữ</td><td><strong>Nam tính</strong> (1 điều kiện nam hóa, 1 nữ hóa)</td></tr></tbody></table><p><strong>Cách tính chỉ là kiểm đếm sơ bộ</strong> của mình: sách chỉ nói sign quan trọng nhất, chưa dạy cách cân các điều kiện, nên đây là bài tập tư duy.</p><h3 id="nhan-xet-tu-ket-qua" tabindex="-1">Nhận xét từ kết quả <a class="header-anchor" href="#nhan-xet-tu-ket-qua" aria-label="Permalink to &quot;Nhận xét từ kết quả&quot;">​</a></h3><ol><li><strong>Hai hành tinh nữ (Moon, Venus) đều bị nam hóa</strong>: cả hai ở sign nam, cùng buổi sáng. Theo mô hình của sách, năng lượng của chúng &quot;chủ động và nhanh hơn&quot; mức thường của hành tinh nữ. Với Venus (chart ruler) và Moon (ánh sáng chủ của lá số đêm), điều đó có thể nghĩa là tình cảm, cảm xúc và thân thể có xu hướng <strong>biểu hiện sớm, chủ động</strong> hơn là chờ đợi. Đây chỉ là diễn giải theo logic của sách.</li><li><strong>Mars, Jupiter, Sun gần như hoàn toàn nam</strong>: nhiều điều kiện cùng hướng.</li><li><strong>Mercury là hành tinh nên để ý nhất</strong>: là hành tinh linh hoạt, bị chậm lại ở sign nữ, nhưng vừa buổi sáng. Kết quả đổi tùy cách đo quadrant.</li><li><strong>Liên hệ với việc đoán thời điểm</strong> (mục 1h của Phần 1) [Bổ sung, mở rộng của mình]: các chủ đề của hành tinh nam hóa (Mars chủ house 2 và 7, Jupiter chủ house 3 và 6) có thể &quot;tiến nhanh&quot;, còn các chủ đề của hành tinh ít nam hóa hơn (Saturn chủ house 4 và 5, Mercury chủ house 9 và 12) có thể &quot;chín muộn&quot; hơn. Sách chưa dạy cách dùng này, hãy coi như hướng gợi ý.</li></ol><hr><h2 id="_5-tong-hop-bon-đieu-kien" tabindex="-1">5. Tổng hợp bốn điều kiện <a class="header-anchor" href="#_5-tong-hop-bon-đieu-kien" aria-label="Permalink to &quot;5. Tổng hợp bốn điều kiện&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Điều kiện</th><th>Nam hóa</th><th>Nữ hóa</th><th>Cần dữ liệu gì</th><th>Độ khó</th></tr></thead><tbody><tr><td><strong>1. Sign</strong> (quan trọng nhất)</td><td>Aries, Gemini, Leo, Libra, Sagittarius, Aquarius</td><td>Taurus, Cancer, Virgo, Scorpio, Capricorn, Pisces</td><td>Sign của hành tinh</td><td>Dễ</td></tr><tr><td><strong>2. Solar phase</strong></td><td>Buổi sáng (số độ nhỏ hơn Sun)</td><td>Buổi chiều (số độ lớn hơn Sun)</td><td>Độ của hành tinh và Sun</td><td>Vừa</td></tr><tr><td><strong>3. Quadrant</strong></td><td>Asc → MC; Dsc → IC</td><td>MC → Dsc; IC → Asc</td><td>House hoặc độ của các góc</td><td>Vừa (có hai cách)</td></tr><tr><td><strong>4. Latitude</strong></td><td>Bắc</td><td>Nam</td><td>Cột vĩ độ trong phần mềm</td><td>Cần thêm dữ liệu</td></tr></tbody></table><p><strong>Cách dùng thực tế</strong> [Bổ sung, gợi ý của mình]:</p><ol><li>Bắt đầu bằng <strong>giới gốc</strong> của hành tinh.</li><li>Xét <strong>sign</strong> trước (yếu tố quan trọng nhất).</li><li>Thêm <strong>phase</strong>, <strong>quadrant</strong>, <strong>latitude</strong>.</li><li>Đặt kết quả lên <strong>thang Table 8</strong> (xem Phần 1): nhiều điều kiện cùng hướng với giới gốc thì &quot;cực kỳ&quot;, điều kiện ngược hướng thì &quot;pha trộn&quot;.</li><li>Ghi chú <strong>cách đo quadrant</strong> bạn đã dùng (theo house hay theo độ).</li></ol><hr><h2 id="_6-khi-xem-la-so-cho-nguoi-khac-bo-sung" tabindex="-1">6. Khi xem lá số cho người khác [Bổ sung] <a class="header-anchor" href="#_6-khi-xem-la-so-cho-nguoi-khac-bo-sung" aria-label="Permalink to &quot;6. Khi xem lá số cho người khác [Bổ sung]&quot;">​</a></h2><ul><li>Dùng <strong>ngôn ngữ năng lượng</strong> (chủ động và nhanh so với thong thả và chín muộn), không gắn với giới tính của người đó.</li><li>Với solar phase: &quot;hành tinh này mọc trước Sun nên có xu hướng chủ động, hành động sớm&quot; hoặc &quot;mọc sau Sun nên có xu hướng chờ, chín muộn&quot;. Câu so sánh buổi sáng và buổi chiều của sách (con người tràn năng lượng buổi sáng, thư giãn buổi chiều) là hình ảnh dễ dùng.</li><li>Nói rõ nếu <strong>hai cách đo quadrant</strong> cho kết quả khác nhau.</li><li>Nếu người đối diện chia sẻ về bản dạng giới của mình, sách gợi ý các điều chỉnh này có thể giúp hiểu sự linh hoạt giới. Nhưng bạn đừng tự suy ra từ lá số.</li><li>Không nói theo kiểu định kiến giới (xem lưu ý về Rhetorius ở Phần 1).</li></ul><hr><h2 id="_7-tu-kiem-tra" tabindex="-1">7. Tự kiểm tra <a class="header-anchor" href="#_7-tu-kiem-tra" aria-label="Permalink to &quot;7. Tự kiểm tra&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Câu hỏi</th><th>Đáp án</th></tr></thead><tbody><tr><td>Hành tinh nào nam hóa theo solar phase?</td><td>Hành tinh mọc trước Sun (buổi sáng), số độ nhỏ hơn Sun</td></tr><tr><td>Sun ở 15° Leo, Mercury ở 5° Virgo thì pha nào?</td><td>Buổi chiều (số độ lớn hơn Sun), nữ hóa</td></tr><tr><td>Vùng điều chỉnh solar phase nằm từ đâu đến đâu?</td><td>Từ 15° đến 120° tính từ Sun</td></tr><tr><td>Quadrant nào nam, quadrant nào nữ?</td><td>Asc → MC và Dsc → IC là nam; MC → Dsc và IC → Asc là nữ</td></tr><tr><td>Gợi ý cách nhớ quadrant?</td><td>Tiến tới điểm cực (MC hoặc IC) là nam, rời khỏi là nữ</td></tr><tr><td>Vĩ độ bắc thì sao?</td><td>Nam hóa</td></tr><tr><td>Vĩ độ khác declination thế nào?</td><td>Vĩ độ đo so với ecliptic, declination đo so với xích đạo thiên cầu</td></tr><tr><td>Sun có vĩ độ bao nhiêu?</td><td>0 (luôn nằm trên ecliptic)</td></tr><tr><td>Sách chưa rõ điều gì về quadrant?</td><td>Phân định theo whole sign hay theo độ chính xác của các góc</td></tr></tbody></table><hr><h2 id="_8-tu-vung-kho" tabindex="-1">8. Từ vựng khó <a class="header-anchor" href="#_8-tu-vung-kho" aria-label="Permalink to &quot;8. Từ vựng khó&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tiếng Anh</th><th>Tiếng Việt</th></tr></thead><tbody><tr><td>Solar phase</td><td>Pha so với Sun</td></tr><tr><td>Morning / evening phase</td><td>Pha buổi sáng / buổi chiều</td></tr><tr><td>Diurnal motion</td><td>Chuyển động ngày (bầu trời quay mỗi ngày)</td></tr><tr><td>Zodiacal longitude</td><td>Kinh độ hoàng đạo (số độ trên vòng hoàng đạo)</td></tr><tr><td>Opposition degree</td><td>Độ đối của Sun (cách Sun 180°)</td></tr><tr><td>Retrograde / direct station</td><td>Trạm nghịch hành / thuận hành (lúc hành tinh đổi hướng)</td></tr><tr><td>Quadrant</td><td>Góc phần tư</td></tr><tr><td>Culminating / anti-culminating</td><td>Điểm culminating (đỉnh) / anti-culminating (đáy)</td></tr><tr><td>Nadir</td><td>Đáy bầu trời (IC)</td></tr><tr><td>Ecliptic</td><td>Hoàng đạo (đường đi biểu kiến của Sun)</td></tr><tr><td>Celestial equator</td><td>Xích đạo thiên cầu</td></tr><tr><td>Celestial latitude</td><td>Vĩ độ thiên thể</td></tr><tr><td>Declination</td><td>Độ xích vĩ (lệch so với xích đạo thiên cầu)</td></tr><tr><td>Out of bounds</td><td>Vượt biên (declination vượt giới hạn)</td></tr></tbody></table><hr><h2 id="_9-đieu-can-kiem-chung" tabindex="-1">9. Điều cần kiểm chứng <a class="header-anchor" href="#_9-đieu-can-kiem-chung" aria-label="Permalink to &quot;9. Điều cần kiểm chứng&quot;">​</a></h2><ul><li>Bản dịch dựa trên các trang bạn chụp. Sách hẹn giải thích đầy đủ hơn về sao buổi sáng và buổi chiều ở Phần Ba, nên có thể có thêm quy tắc.</li><li>Cách mình hiểu vùng điều chỉnh solar phase (trong 15° và quá 120° là không điều chỉnh) là suy luận từ câu của sách, chưa được nêu thẳng.</li><li>Các độ của Asc, MC, Dsc, IC trong lá số mẫu là ước lượng. Kết quả quadrant theo độ của Moon (cách Asc khoảng 15°) và Mercury (cách IC khoảng 14°) khá nhạy với ước lượng này.</li><li>Bảng lá số mẫu chưa có vĩ độ thiên thể, nên phần tổng hợp chưa đầy đủ.</li><li>Suy luận về Moon theo pha trăng, về Venus sao Mai và sao Hôm, và việc dùng giới tính để đoán nhịp độ chủ đề house là cách mình đọc thêm, không phải lập luận tác giả nêu rõ.</li><li>Các số liệu thiên văn (độ nghiêng 23.4°, khoảng cách tối đa của Mercury và Venus) là kiến thức chung của mình, chưa kiểm chứng với nguồn.</li></ul>',102)])])}const v=t(d,[["render",u]]);export{p as __pageData,v as default};
